        LINE_OF_BUSINESS: {
            PROPERTY:        'property',
            AUTO:            'auto',
            MOTOR:           'motor',
            WORKERS_COMP:    'workers_comp',
            GENERAL:         'general',
            CASUALTY:        'casualty',
            MARINE:          'marine',
            ENERGY:          'energy',
            FINANCIAL_LINES: 'financial_lines',
            CONSTRUCTION:    'construction',
            AVIATION:        'aviation',
            CYBER:           'cyber',
            SPECIALTY:       'specialty'
        },

