            ALL:          SHARED.ALL,
            NEW_BUSINESS: SHARED.NEW_BUSINESS,
            RENEWAL:      SHARED.RENEWAL
        },

        // loa_authority_limit.bind_authority -- what the holder may actually DO
        // once inside the limit. QUOTE_ONLY is the carve-out that lets a class be
        // quoted at a tier but never bound there.
        LOA_BIND_AUTHORITY: {
            QUOTE_AND_BIND: 'quote_and_bind',
            QUOTE_ONLY:     'quote_only',
            REFER_ONLY:     'refer_only'
        },

        // loa_authority_grant.grantee_type -- ROLE is the standing grant and needs
        // no maintenance when a person joins, moves or leaves. USER is the named
        // exception, normally a delegation.
        LOA_GRANTEE_TYPE: {
            ROLE: 'role',
            USER: 'user'
        },

        // loa_authority_grant.state -- the ONLY lifecycle field on a grant. There
        // is deliberately no `active` boolean beside it: two fields that can
        // disagree about whether authority is live is a bug waiting to happen.
        LOA_GRANT_STATE: {
            DRAFT:      SHARED.DRAFT,
            ACTIVE:     SHARED.ACTIVE,
            SUPERSEDED: SHARED.SUPERSEDED,
            REVOKED:    SHARED.REVOKED,
            EXPIRED:    SHARED.EXPIRED
        },

        // loa_evaluation.evaluation_trigger -- why this VERSION of the evaluation
        // exists. Evaluations are never updated in place; a change writes a new
        // version and deactivates the last.
        LOA_EVALUATION_TRIGGER: {
            INITIAL_EVALUATION:  'initial_evaluation',
            INTAKE_CHANGE:       'intake_change',
            EXPOSURE_CHANGE:     'exposure_change',
            GRANT_CHANGE:        'grant_change',
            QUOTE_CHANGE:        'quote_change',
            MANUAL_REEVALUATION: 'manual_reevaluation'
        },

        // loa_evaluation.evaluation_status -- the decision. NO_AUTHORITY means no
        // grant matched at all, which is a different problem from a breach and
        // must never be reported as one: a breach means the underwriter is over
        // their limit, no_authority means they have no limit on this LOB.
        LOA_EVALUATION_STATUS: {
            PENDING:                           SHARED.PENDING,
            AUTHORIZED:                        'authorized',
            BREACH:                            'breach',
            // 'referred' (the decision), NOT SHARED.REFERRAL ('referral', the
            // case_task category). Two different words for two different things.
            REFERRED:                          'referred',
            REFERRED_APPROVED:                 'referred_approved',
            REFERRED_APPROVED_WITH_CONDITIONS: 'referred_approved_with_conditions',
            REFERRED_REJECTED:                 'referred_rejected',
            REFERRED_REJECTED_ALTERNATE_TERMS: 'referred_rejected_alternate_terms',
            DECLINED:                          SHARED.DECLINED,
            NO_AUTHORITY:                      'no_authority'
        },

        // loa_evaluation_line.result -- the per-metric outcome. NO_LIMIT means the
        // tier has no limit row for that metric, which is NOT the same as being
        // within one; reporting it as WITHIN would hide a gap in the grid.
        LOA_LINE_RESULT: {
            WITHIN:         'within',
            BREACH:         'breach',
            NOT_APPLICABLE: 'not_applicable',
            NO_LIMIT:       'no_limit'
        },

        // OPEN ITEM: exposure_peril.peril carries an uncatalogued list that predates
        // CHOICE.PERIL above. Reconciling the two is a data decision (it would
        // rewrite live exposure_peril rows), not a cleanup - leave both until it is
        // taken deliberately.

        // =================================================================
        // MODULE EXECUTION PLAN  --  x_gegis_ins_policy_module_plan
        // -----------------------------------------------------------------
        // The plan is a flat matrix: one row per situation, one order column
        // per module. 0 = do not create; equal numbers = run in parallel;
        // higher = runs after. Restart is per module, in its own column.
        // =================================================================

        // Module identity. Deliberately an ALIAS of STAGE rather than a new
        // list: a module and the submission stage it drives are the same
        // thing, and reusing these lower_snake_case tokens retires the
        // UPPERCASE codes (and the EXPOSURE_MANAGMENT misspelling) that the
        // licence JSON and UwmConstants disagree on.
        MODULE: STAGE,

        // module_plan.request_kind - is this the first request or a revision?
        REQUEST_KIND: {
            NEW:    SHARED.NEW,
            UPDATE: 'update'
        },

        // module_plan.sub_type / submission.sub_type. Optional everywhere:
        // BLANK matches any sub type, so New Business rows can leave it empty
        // and pick it up later without a schema change.
        // Renewal tiers reuse the SHARED renewal decision tokens; the MTA
        // tokens are new - a material change reopens underwriting, a
        // non-material one does not.
        SUB_TYPE: {
            FULL_UW:      SHARED.FULL_RE_UNDERWRITING,
            FAST_TRACK:   'fast_track',
            AUTO_APPROVE: SHARED.AUTO_RENEW,
            MATERIAL:     'material',
            NON_MATERIAL: 'non_material'
        },

        // module_plan.config_mode. In ADVANCED mode every order and restart
        // column on the row is ignored and advanced_script decides.
        CONFIG_MODE: {
            SIMPLE:   'simple',
            ADVANCED: 'advanced'
        },

        // module_plan.restart_clearance / _risk / _exposure / _quote_and_bind.
        // Applies only when submission_on_update = override; on a new
        // submission version the cases are created fresh by the plan.
        RESTART_MODE: {
            NONE:        'none',
            OVERRIDE:    SHARED.OVERRIDE,
            NEW_VERSION: SHARED.NEW_VERSION
        },

        // module_plan.submission_on_update - what happens to the submission
        // RECORD, as opposed to its module cases.
        SUBMISSION_UPDATE_MODE: {
            OVERRIDE:    SHARED.OVERRIDE,
            NEW_VERSION: SHARED.NEW_VERSION
        },

        // version_copy_rule.action - what happens to each related table when a
        // new submission version is cut. Nothing is copied implicitly: only a
        // table with an explicit COPY rule travels, so a child table nobody
        // catalogued cannot ride along on its copied parent.
        COPY_ACTION: {
            COPY:   'copy',
            MOVE:   'move',
            CANCEL: 'cancel',
            SKIP:   'skip'
        },

        // module_plan.line_of_business carries the LINE_OF_BUSINESS values
        // above PLUS this wildcard, matching the sentinel already used by
        // extraction_mapping.line_of_business.
        LOB_ALL: 'all'
    };

    // Collect the value strings of a choice group as an array (for IN queries,
    // validation, etc.). Skips function members such as ACTIVITY.all.
    function values(map) {
        var out = [];
        for (var k in map) {
            if (map.hasOwnProperty(k) && typeof map[k] === 'string')
                out.push(map[k]);
        }
        return out;
    }

    // ---------------------------------------------------------------------
    // Generic typed getters. dflt is optional; when omitted the registered
    // DEFAULT for that property (or a safe empty/false) is used.
    // ---------------------------------------------------------------------
    function getString(name, dflt) {
        var d = (dflt !== undefined) ? dflt : (DEFAULT[name] !== undefined ? DEFAULT[name] : '');
        return gs.getProperty(name, d);
    }

    function getBool(name, dflt) {
        var d = (dflt !== undefined) ? (dflt ? 'true' : 'false')
                                     : (DEFAULT[name] !== undefined ? DEFAULT[name] : 'false');
        return getString(name, d) === 'true';
    }

    // Parse a JSON-valued property. Returns the parsed object, or dflt
    // (default {}) when the property is empty or not valid JSON.
    function getJson(name, dflt) {
        var fallback = (dflt !== undefined) ? dflt : {};
        var raw = getString(name, '');
        if (!raw)
            return fallback;
        try {
            var parsed = JSON.parse(raw);
            return (parsed && typeof parsed === 'object') ? parsed : fallback;
        } catch (e) {
            gs.warn('[Constants] property ' + name + ' is not valid JSON: ' + e.message);
            return fallback;
        }
    }

    // ---------------------------------------------------------------------
    // Domain helpers.
    // ---------------------------------------------------------------------
    // intent: 'new' (POST /submission) | 'update' (PUT /submission/{number}).
    // Returns true when that intent's extraction should be auto-approved.
    function isAutoApprove(intent) {
        return (String(intent) === 'update')
            ? getBool(PROP.AUTO_APPROVE_UPDATE)
            : getBool(PROP.AUTO_APPROVE_NEW);
    }

    // Parsed license + staged execution plan. Empty object if unset/invalid.
    function getModuleExecutionConfig() {
        return getJson(PROP.MODULE_EXECUTION_CONFIG, {});
    }

    // ---------------------------------------------------------------------
    // Licence. Issued, not configured - it outranks the module plan, so a
    // module the customer has not licensed can never be activated no matter
    // how the plan (or an advanced script) is written.
    // ---------------------------------------------------------------------
    function getLicence() {
        var cfg = getModuleExecutionConfig();
        return {
            instance_id:      cfg.instance_id || '',
            customer_name:    cfg.customer_name || '',
            license_version:  cfg.license_version || '',
            expires_at:       cfg.expires_at || '',
            licensed_modules: cfg.licensed_modules || []
        };
    }

    // ISO-8601 ('2027-03-10T00:00:00Z') to the format GlideDateTime parses.
    function isoToGlide(iso) {
        return String(iso || '').replace('T', ' ').replace('Z', '').split('.')[0];
    }

    // No expires_at at all is treated as EXPIRED, not as perpetual - a missing
    // licence must fail closed.
    function isLicenceValid() {
        var expires = isoToGlide(getLicence().expires_at);
        if (!expires) {
            gs.error('[Constants] licence has no expires_at - treating as expired');
            return false;
        }
        return new GlideDateTime().compareTo(new GlideDateTime(expires)) < 0;
    }

    // licenceCode is the UPPERCASE code carried in licensed_modules
    // (SUBMISSION_CLEARANCE, EXPOSURE_MANAGEMENT, ...). Callers resolve a
    // module's licence code from the module registry, not from a hard-coded map.
    function isModuleLicensed(licenceCode) {
        if (!isLicenceValid())
            return false;
        var wanted = String(licenceCode || '').trim().toUpperCase();
        if (!wanted)
            return false;
        var licensed = getLicence().licensed_modules;
        for (var i = 0; i < licensed.length; i++) {
            if (String(licensed[i]).trim().toUpperCase() === wanted)
                return true;
        }
        return false;
    }

    return {
        SCOPE: SCOPE,
        PROP: PROP,
        TABLE: TABLE,
        CHOICE: CHOICE,
        values: values,
        getString: getString,
        getBool: getBool,
        getJson: getJson,
        isAutoApprove: isAutoApprove,
        getModuleExecutionConfig: getModuleExecutionConfig,
        getLicence: getLicence,
        isLicenceValid: isLicenceValid,
        isModuleLicensed: isModuleLicensed
    };
})();
